const r = await tools.exec_command({
  cmd:"git worktree add --detach .worktrees/pr-2052 origin/pr/2052",
  workdir:"/Users/peytonmontei/Documents/entire/devenv/entireio/cli",
  yield_time_ms:30000,
  max_output_tokens:12000
}); text(r.output)

const wt="/Users/peytonmontei/Documents/entire/devenv/entireio/cli/.worktrees/pr-2052";
const cmds=[
  "git status --short --branch",
  "git rev-parse HEAD origin/pr/2052 origin/main",
  "git merge-base origin/main HEAD",
  "git rev-list --count origin/main..HEAD",
  "git diff --stat origin/main...HEAD",
  "git diff --numstat origin/main...HEAD",
  "git log --format='%H%x00%s%x00%b%x00---END---' origin/main..HEAD",
  "rg --files -g 'AGENTS.md' -g '!vendor'",
  "git diff --name-only origin/main...HEAD"
];
const rs=await Promise.all(cmds.map(cmd=>tools.exec_command({cmd,workdir:wt,yield_time_ms:10000,max_output_tokens:30000})));
for(let i=0;i<rs.length;i++){text(`CMD ${cmds[i]}\nEXIT ${rs[i].exit_code}\n${rs[i].output}`);}

const root="/Users/peytonmontei/Documents/entire/devenv/entireio/cli";
const refs=["test/global-combined","feat/global-settings-tier","feat/global-core","feat/global-invisible","feat/global-writer","feat/global-agent-hooks","feat/global-trust"];
const cmds=[
  "gh issue view 2020 --repo entireio/cli --json number,title,state,body,url --jq '{number,title,state,body,url}'",
  "git log --oneline --decorate e3d8781ab4a0cd3eda0970bedfdbbc4fc435d760..origin/main",
  ...refs.map(ref=>`git log --format='%H %P %s%n%b%n---' --reverse origin/main..${ref}`),
  ...refs.map(ref=>`git diff --stat origin/main...${ref}`)
];
const rs=[];
