136	// UninstallHooks removes Entire hooks from the authoritative and obsolete
137	// worktree-local Codex files.
138	func (c *CodexAgent) UninstallHooks(ctx context.Context) error {
139		location, err := ResolveHookLocation(ctx)
140		if err != nil {
141			var unsupported *UnsupportedHookLocationError
142			if errors.As(err, &unsupported) {
143				return uninstallHooksFiles(ctx, unsupported.Location.LockPath, unsupported.Location.LegacyHooksPath)
