150	func uninstallHooksFiles(ctx context.Context, lockPath string, hooksPaths ...string) error {
151		hasFile := false
152		for _, hooksPath := range hooksPaths {
153			if hooksPath == "" {
154				continue
155			}
156			_, err := os.Stat(hooksPath)
157			if err == nil {
158				hasFile = true
159				continue
160			}
161			if !errors.Is(err, os.ErrNotExist) {
162				return fmt.Errorf("stat %s: %w", hooksPath, err)
163			}
164		}
165		if !hasFile {
166			return nil
167		}
168		if err := os.MkdirAll(filepath.Dir(lockPath), 0o750); err != nil {
169			return fmt.Errorf("create Codex hooks lock directory: %w", err)
170		}
171		release, err := acquireHooksLock(ctx, lockPath)
172		if err != nil {
173			return fmt.Errorf("lock Codex hooks file: %w", err)
174		}
175		defer release()
176	
177		for _, hooksPath := range hooksPaths {
178			if hooksPath == "" {
179				continue
180			}
181			document, readErr := readHooksDocument(hooksPath)
182			if readErr != nil {
183				return readErr
184			}
185			if !document.exists {
186				continue
187			}
188			changed, removeErr := removeEntireHooksFromDocument(document)
189			if removeErr != nil {
