201	// AreHooksInstalled reports whether Codex is wired up to Entire in this repo.
202	//
203	// It requires only the core events, not everything InstallHooks writes today.
204	// The two questions are different: this one decides whether Codex is listed as
205	// an installed agent (`entire status`, the review and investigate pickers), and
206	// answering it with the full set would drop Codex out of all of them the moment
207	// a release adds an event — every existing install predates the addition. Drift
208	// against today's set is part of hook-config inspection, which `entire doctor`
209	// reports with the fix (`entire enable`).
210	func (c *CodexAgent) AreHooksInstalled(ctx context.Context) bool {
211		location, err := ResolveHookLocation(ctx)
212		if err != nil || !location.ProjectLayerExists() {
213			return false
214		}
215		inspection := inspectHookConfigAt(ctx, location.HooksPath)
216		return inspection.State == HookFileEntire && inspection.CoreInstalled
217	}
