219	// CheckHookConfig reports whether Codex's authoritative hook configuration is
220	// absent, current, or needs installation/migration.
221	func (c *CodexAgent) CheckHookConfig(ctx context.Context) agent.HookConfigState {
222		location, err := ResolveHookLocation(ctx)
223		if err != nil {
224			var unsupported *UnsupportedHookLocationError
225			if errors.As(err, &unsupported) && unsupported.Location.LegacyHooksPath != "" && HasWorktreeLocalEntireHooks(ctx) {
226				return agent.HooksOutdated
227			}
228			return agent.HooksAbsent
229		}
230		inspection := inspectHookConfigAt(ctx, location.HooksPath)
231		switch inspection.State {
232		case HookFileInvalid:
