429		if len(document.rawHooks) > 0 {
430			hooksJSON, err := jsonutil.MarshalWithNoHTMLEscape(document.rawHooks)
431			if err != nil {
432				return fmt.Errorf("failed to marshal hooks: %w", err)
433			}
434			document.topLevel["hooks"] = hooksJSON
435		} else {
436			delete(document.topLevel, "hooks")
437		}
438		if len(document.topLevel) == 0 {
439			if err := os.Remove(path); err != nil && !errors.Is(err, os.ErrNotExist) {
440				return fmt.Errorf("remove empty hooks.json: %w", err)
441			}
442			return nil
443		}
444		if err := os.MkdirAll(filepath.Dir(path), 0o750); err != nil {
445			return fmt.Errorf("create .codex directory: %w", err)
446		}
447		output, err := jsonutil.MarshalIndentWithNewline(document.topLevel, "", "  ")
448		if err != nil {
449			return fmt.Errorf("failed to marshal hooks.json: %w", err)
450		}
451		if err := jsonutil.WriteFileAtomic(path, output, 0o600); err != nil {
452			return fmt.Errorf("failed to write hooks.json: %w", err)
453		}
454		document.exists = true
455		return nil
456	}
