458	func acquireHooksLock(ctx context.Context, path string) (func(), error) {
459		return acquireHooksLockWithin(ctx, path, hooksLockWaitTimeout)
460	}
461	
462	func acquireHooksLockWithin(ctx context.Context, path string, wait time.Duration) (func(), error) {
463		const retryDelay = 25 * time.Millisecond
464		lockCtx, cancel := context.WithTimeout(ctx, wait)
465		defer cancel()
466	
467		lock := flock.New(path)
468		locked, err := lock.TryLockContext(lockCtx, retryDelay)
469		if err != nil {
470			if errors.Is(err, context.DeadlineExceeded) && ctx.Err() == nil {
471				return nil, fmt.Errorf(
472					"timed out after %s waiting for another Entire process to update Codex hooks: %w",
473					wait,
474					err,
475				)
476			}
477			return nil, fmt.Errorf("acquire file lock: %w", err)
478		}
479		if !locked {
480			return nil, errors.New("acquire file lock: lock unavailable")
481		}
482		return func() { _ = lock.Unlock() }, nil //nolint:errcheck // The completed mutation cannot be rolled back if unlock reports an error.
483	}
