524	// hookCommandExists reports whether the exact command is already configured
525	// with the timeout we want. The timeout is part of the match so an upgrade
526	// rewrites a hook installed by an older Entire with a different budget —
527	// notably SessionEnd, where a leftover 30s makes Codex print a clamping warning
528	// at every startup.
529	func hookCommandExists(groups []MatcherGroup, command string, timeoutSec int) bool {
530		for _, group := range groups {
531			for _, hook := range group.Hooks {
532				if hook.Command == command && hook.Timeout == timeoutSec {
533					return true
534				}
535			}
536		}
537		return false
538	}
539	
540	// syncHookCommand ensures groups contains exactly the given Entire hook command
541	// at the given timeout, and no other Entire-owned entry, reporting whether the
542	// config changed.
543	//
544	// Stale entries are dropped even when command is already present. Checking
545	// presence first (as this did before) left a hook written by an older version
546	// sitting next to the current one, so both fired — for the removed local-dev mode
547	// that meant a script inside the working tree kept running on every agent turn.
548	func syncHookCommand(groups []MatcherGroup, command string, timeoutSec int) ([]MatcherGroup, bool) {
549		groups, dropped := dropStaleEntireHooks(groups, command, timeoutSec)
550		if hookCommandExists(groups, command, timeoutSec) {
551			return groups, dropped
552		}
553		return addHook(groups, command, timeoutSec), true
554	}
555	
556	// dropStaleEntireHooks removes Entire-owned hooks that are not command at
557	// timeoutSec, per matcher group, pruning groups left with no hooks. See
558	// agent.DropStaleManagedHooks for why this runs on every install.
559	//
560	// The timeout is part of what counts as stale here, which the shared helper
561	// cannot express: it matches on the command alone, and Codex budgets per event.
562	// A SessionEnd hook left at the old 30s keeps its command but makes Codex print
563	// a clamping warning at every startup — see SessionEndTimeoutSec.
564	func dropStaleEntireHooks(groups []MatcherGroup, command string, timeoutSec int) ([]MatcherGroup, bool) {
565		staleTimeout := func(e HookEntry) bool { return e.Command == command && e.Timeout != timeoutSec }
566	
567		result := make([]MatcherGroup, 0, len(groups))
568		dropped := false
569		for _, group := range groups {
570			kept, d := agent.DropStaleManagedHooks(group.Hooks, hookEntryCommand, []string{command})
571			if d {
572				dropped = true
573			}
574			// Clone before deleting: with nothing dropped above, kept still aliases
575			// the caller's slice.
576			if slices.ContainsFunc(kept, staleTimeout) {
577				kept = slices.DeleteFunc(slices.Clone(kept), staleTimeout)
578				dropped = true
579			}
580			if len(kept) > 0 {
581				group.Hooks = kept
582				result = append(result, group)
583			}
584		}
585		if !dropped {
586			return groups, false
587		}
588		return result, true
589	}
