594	func addHook(groups []MatcherGroup, command string, timeoutSec int) []MatcherGroup {
595		entry := HookEntry{
596			Type:    "command",
597			Command: command,
598			Timeout: timeoutSec,
599		}
600	
601		// Add to an existing group with null matcher, or create a new one
602		for i, group := range groups {
603			if group.Matcher == nil {
604				groups[i].Hooks = append(groups[i].Hooks, entry)
605				return groups
606			}
607		}
608		return append(groups, MatcherGroup{
609			Matcher: nil,
610			Hooks:   []HookEntry{entry},
611		})
612	}
