 	}
 	l, err := logging.New(logging.Config{
 		Dir:   filepath.Join(root, logging.LogsDir),
 		Level: resolveLogLevel(ctx),
 	})
 	if err != nil {
 		return nil, fmt.Errorf("open log sink: %w", err)
