   315	func inspectHookConfigAt(ctx context.Context, path string) HookConfigInspection {
   316		document, err := readHooksDocument(path)
   317		if err != nil {
   318			return HookConfigInspection{State: HookFileInvalid, Err: err}
   319		}
   320		if !document.exists {
   321			return HookConfigInspection{State: HookFileAbsent}
   322		}
   323	
   324		inspection := HookConfigInspection{
   325			State:         HookFileUserOnly,
   326			Current:       true,
   327			CoreInstalled: true,
   328		}
   329		for _, spec := range managedHookSpecs(ctx) {
   330			var groups []MatcherGroup
   331			if err := parseHookType(document.rawHooks, spec.event, &groups); err != nil {
   332				return HookConfigInspection{State: HookFileInvalid, Err: err}
   333			}
   334			installed := hasEntireHook(groups)
   335			if installed {
   336				inspection.State = HookFileEntire
   337			} else {
   338				inspection.Missing = append(inspection.Missing, spec.label)
   339				if spec.core {
   340					inspection.CoreInstalled = false
   341				}
   342			}
   343			if !managedHookIsCurrent(groups, spec.command, spec.timeout) {
   344				inspection.Current = false
   345			}
   346		}
   347		if inspection.State == HookFileUserOnly {
   348			inspection.Missing = nil
   349			inspection.Current = false
   350			inspection.CoreInstalled = false
   351		}
   352		return inspection
   353	}
