   362			return document, nil
   363		}
   364		if err != nil {
   365			return nil, fmt.Errorf("read %s: %w", path, err)
   366		}
   367		document.exists = true
   368		if err := json.Unmarshal(data, &document.topLevel); err != nil {
   369			return nil, fmt.Errorf("failed to parse existing hooks.json: %w", err)
   370		}
   371		if document.topLevel == nil {
