1505				return fmt.Errorf("failed to save settings: %w", err)
1506			}
1507			// Also update local if it exists, so it doesn't override.
1508			if localExists(ctx) {
1509				if err := setEnabledRaw(ctx, settings.LoadLocalRaw, settings.SaveLocalRaw, enabled); err != nil {
1510					return fmt.Errorf("failed to save local settings: %w", err)
1511				}
1512			}
1513		} else {
1514			if err := setEnabledRaw(ctx, settings.LoadLocalRaw, settings.SaveLocalRaw, enabled); err != nil {
1515				return fmt.Errorf("failed to save local settings: %w", err)
1516			}
1517		}
1518		return nil
1519	}
