1450	// runDisable flips the enabled flag to false in the resolved settings scope.
1451	//
1452	// Scope resolution is deliberately asymmetric with enable because
1453	// settings.local.json overrides settings.json in the merged view:
1454	//   - bare `entire disable` (and --local) writes settings.local.json — the
1455	//     minimal, always-effective way to silence Entire on one machine without
1456	//     editing committed team config;
1457	//   - --project writes the committed settings.json (and setEnabledFlag also
1458	//     syncs the local file if present, so a stale local override can't leave
1459	//     the repo enabled).
1460	//
1461	// This restores origin/main's default (bare disable -> local) and matches the
1462	// --project flag's help text. Enable, by contrast, must reach the committed
1463	// file to recover a project the user disabled there, so it resolves via
1464	// settingsTargetFile (see runEnableOnConfiguredRepo). --local is accepted for
1465	// symmetry with enable; for disable it is the same as the bare default.
1466	func runDisable(ctx context.Context, w io.Writer, useProjectSettings bool) error {
1467		targetFile := settings.EntireSettingsLocalFile
1468		configDisplay := configDisplayLocal
1469		if useProjectSettings {
1470			targetFile = settings.EntireSettingsFile
1471			configDisplay = configDisplayProject
1472		}
1473	
1474		if err := setEnabledFlag(ctx, false, targetFile == settings.EntireSettingsFile); err != nil {
1475			return err
1476		}
1477	
1478		fmt.Fprintf(w, "Entire is now disabled (%s).\n", configDisplay)
1479		return nil
1480	}
