1521	// setEnabledRaw loads a settings file via load, sets its "enabled" key, and
1522	// writes it back via save, preserving every other key already in that file.
1523	func setEnabledRaw(
1524		ctx context.Context,
1525		load func(context.Context) (path string, raw map[string]json.RawMessage, exists bool, err error),
1526		save func(path string, raw map[string]json.RawMessage) error,
1527		enabled bool,
1528	) error {
1529		path, raw, _, err := load(ctx)
1530		if err != nil {
1531			return err
1532		}
1533		value, err := json.Marshal(enabled)
1534		if err != nil {
1535			return fmt.Errorf("marshal enabled flag: %w", err)
1536		}
1537		raw["enabled"] = value
1538		return save(path, raw)
1539	}
