1541	// saveEnabledState writes the caller-provided, already-target-scoped struct s
1542	// to the target file, then applies the same one-directional project -> local
1543	// sync of the "enabled" key as setEnabledFlag (see that function for the full
1544	// merged-vs-scoped rationale). s must already be scoped to the target file's
1545	// own content: it is intentionally NOT written into the other scope, which
1546	// would overwrite that file's own fields (log_level, absolute_git_hook_path, personal
1547	// strategy_options, ...) — the same leak this rule prevents, in the other
1548	// direction.
1549	func saveEnabledState(ctx context.Context, s *EntireSettings, useProjectSettings bool) error {
1550		if useProjectSettings {
1551			if err := SaveEntireSettings(ctx, s); err != nil {
1552				return fmt.Errorf("failed to save settings: %w", err)
1553			}
1554			// Also sync just the enabled key to local if it exists, so it doesn't override.
1555			if localExists(ctx) {
1556				if err := setEnabledRaw(ctx, settings.LoadLocalRaw, settings.SaveLocalRaw, s.Enabled); err != nil {
1557					return fmt.Errorf("failed to save local settings: %w", err)
1558				}
1559			}
1560		} else {
1561			if err := SaveEntireSettingsLocal(ctx, s); err != nil {
1562				return fmt.Errorf("failed to save local settings: %w", err)
1563			}
1564		}
1565		return nil
1566	}
