1450	// runDisable flips the enabled flag to false in the resolved settings scope.
1451	//
1452	// Scope resolution is deliberately asymmetric with enable because
1453	// settings.local.json overrides settings.json in the merged view:
1454	//   - bare `entire disable` (and --local) writes settings.local.json — the
1455	//     minimal, always-effective way to silence Entire on one machine without
1456	//     editing committed team config;
1457	//   - --project writes the committed settings.json (and setEnabledFlag also
1458	//     syncs the local file if present, so a stale local override can't leave
1459	//     the repo enabled).
1460	//
1461	// This restores origin/main's default (bare disable -> local) and matches the
1462	// --project flag's help text. Enable, by contrast, must reach the committed
1463	// file to recover a project the user disabled there, so it resolves via
1464	// settingsTargetFile (see runEnableOnConfiguredRepo). --local is accepted for
1465	// symmetry with enable; for disable it is the same as the bare default.
1466	func runDisable(ctx context.Context, w io.Writer, useProjectSettings bool) error {
1467		targetFile := settings.EntireSettingsLocalFile
1468		configDisplay := configDisplayLocal
1469		if useProjectSettings {
1470			targetFile = settings.EntireSettingsFile
1471			configDisplay = configDisplayProject
1472		}
1473	
1474		if err := setEnabledFlag(ctx, false, targetFile == settings.EntireSettingsFile); err != nil {
1475			return err
1476		}
1477	
1478		fmt.Fprintf(w, "Entire is now disabled (%s).\n", configDisplay)
1479		return nil
1480	}
1481	
1482	// setEnabledFlag flips only the "enabled" key in the target scope's settings
1483	// file, and — when writing the project scope — also syncs that one key into
1484	// settings.local.json if it exists. The sync is one-directional (project ->
1485	// local) because settings.local.json overrides settings.json in the merged
1486	// view, so a stale local "enabled": false would otherwise keep the repo
1487	// disabled after a project-scope re-enable.
1488	//
1489	// This is the canonical explanation of the merged-vs-scoped write rule that the
1490	// whole enable/disable surface follows; other sites point here.
1491	//
1492	// The write path stays scoped to a single file's own raw JSON on purpose.
1493	// Enable/disable *read* current state through the LoadEntireSettings merged
1494	// view (e.g. IsEnabled), which flattens settings.local.json overrides
1495	// (log_level, absolute_git_hook_path, personal strategy_options/checkpoint_remote, ...) on
1496	// top of settings.json. Writing that merged struct back into one file would
1497	// leak a developer's local-only overrides into the shared, committed project
1498	// file whenever a write resolves to settings.json. setEnabledRaw
1499	// therefore edits only the "enabled" key in each file's own content; its
1500	// sibling saveEnabledState applies the same rule to a caller-provided,
1501	// already-target-scoped struct.
1502	func setEnabledFlag(ctx context.Context, enabled, useProjectSettings bool) error {
1503		if useProjectSettings {
1504			if err := setEnabledRaw(ctx, settings.LoadProjectRaw, settings.SaveProjectRaw, enabled); err != nil {
1505				return fmt.Errorf("failed to save settings: %w", err)
1506			}
1507			// Also update local if it exists, so it doesn't override.
1508			if localExists(ctx) {
1509				if err := setEnabledRaw(ctx, settings.LoadLocalRaw, settings.SaveLocalRaw, enabled); err != nil {
1510					return fmt.Errorf("failed to save local settings: %w", err)
1511				}
1512			}
1513		} else {
1514			if err := setEnabledRaw(ctx, settings.LoadLocalRaw, settings.SaveLocalRaw, enabled); err != nil {
1515				return fmt.Errorf("failed to save local settings: %w", err)
1516			}
1517		}
1518		return nil
1519	}
1520	
1521	// setEnabledRaw loads a settings file via load, sets its "enabled" key, and
1522	// writes it back via save, preserving every other key already in that file.
1523	func setEnabledRaw(
1524		ctx context.Context,
1525		load func(context.Context) (path string, raw map[string]json.RawMessage, exists bool, err error),
1526		save func(path string, raw map[string]json.RawMessage) error,
1527		enabled bool,
1528	) error {
1529		path, raw, _, err := load(ctx)
1530		if err != nil {
1531			return err
1532		}
1533		value, err := json.Marshal(enabled)
1534		if err != nil {
1535			return fmt.Errorf("marshal enabled flag: %w", err)
1536		}
1537		raw["enabled"] = value
1538		return save(path, raw)
1539	}
1540	
1541	// saveEnabledState writes the caller-provided, already-target-scoped struct s
1542	// to the target file, then applies the same one-directional project -> local
1543	// sync of the "enabled" key as setEnabledFlag (see that function for the full
1544	// merged-vs-scoped rationale). s must already be scoped to the target file's
1545	// own content: it is intentionally NOT written into the other scope, which
1546	// would overwrite that file's own fields (log_level, absolute_git_hook_path, personal
1547	// strategy_options, ...) — the same leak this rule prevents, in the other
1548	// direction.
1549	func saveEnabledState(ctx context.Context, s *EntireSettings, useProjectSettings bool) error {
1550		if useProjectSettings {
1551			if err := SaveEntireSettings(ctx, s); err != nil {
1552				return fmt.Errorf("failed to save settings: %w", err)
1553			}
1554			// Also sync just the enabled key to local if it exists, so it doesn't override.
1555			if localExists(ctx) {
1556				if err := setEnabledRaw(ctx, settings.LoadLocalRaw, settings.SaveLocalRaw, s.Enabled); err != nil {
1557					return fmt.Errorf("failed to save local settings: %w", err)
1558				}
1559			}
1560		} else {
1561			if err := SaveEntireSettingsLocal(ctx, s); err != nil {
1562				return fmt.Errorf("failed to save local settings: %w", err)
1563			}
1564		}
1565		return nil
1566	}
1567	
1568	// localExists checks if settings.local.json exists.
1569	func localExists(ctx context.Context) bool {
1570		localFile := settings.EntireSettingsLocalFile
1571		if abs, err := paths.AbsPath(ctx, localFile); err == nil {
1572			localFile = abs
1573		}
1574		_, err := os.Lstat(localFile)
1575		return err == nil
1576	}
