512	// checkGitHooks reports whether Entire's git hooks are installed and current,
513	// and offers to reinstall them when they are not.
514	//
515	// This is the one hook surface a user cannot see going wrong. Agent hook configs
516	// are committed files that turn up in a diff; .git/hooks is per-clone and
517	// untracked, so pulling a release that changes hook generation never touches it.
518	// A hook left by the removed local-dev mode still carries Entire's marker, so it
519	// looks installed while naming a launcher inside the working tree that no longer
520	// exists — and because that shape got no availability guard while pre-push
521	// deliberately propagates exit codes, the symptom a user actually sees is `git
522	// push` being rejected.
523	//
524	// Unlike the agent hook checks this one repairs rather than only warning: the
525	// reinstall is content-idempotent, backs up any foreign hook it displaces, and
526	// writes exactly what the next turn-start would write anyway. Someone reaching
527	// for doctor after a rejected push wants to be unblocked, not handed a second
528	// command to run.
529	func checkGitHooks(cmd *cobra.Command, force bool) error {
530		ctx := cmd.Context()
531		w := cmd.OutOrStdout()
532	
533		switch strategy.CheckGitHookState(ctx) {
534		case strategy.GitHooksCurrent:
535			fmt.Fprintln(w, "✓ Git hooks: OK")
536			return nil
537	
538		case strategy.GitHooksAbsent:
539			// Missing hooks are only a problem where Entire was actually set up.
540			// doctor runs in any git repo, so treating this as actionable would let
541			// `entire doctor --force` install hooks into — and back up the existing
542			// hooks of — a repo that never opted in. That is the loudest possible
543			// surprise from a diagnostic command. The sibling checks already hold this
544			// line: checkHookDrift stays silent on HooksAbsent, and
545			// checkCodexHookTrust returns early when there is no codex hooks file.
546			//
547			// IsSetUpAny rather than IsSetUpAndEnabled: a repo that ran `entire
548			// disable` still wants working hooks, because the hooks themselves are
549			// what no-op while disabled.
550			if !settings.IsSetUpAny(ctx) {
551				return nil
552			}
553			fmt.Fprintln(w, "Git hooks: NOT INSTALLED")
554			fmt.Fprintln(w, "  Commits in this repository are not captured as checkpoints.")
555	
556		case strategy.GitHooksOutdated:
557			// Actionable whatever the settings say: a hook carrying Entire's marker
558			// means this repo opted in at some point, and a stale one is actively
559			// broken rather than merely missing.
560			fmt.Fprintln(w, "Git hooks: OUT OF DATE")
561			fmt.Fprintln(w, "  A hook still runs Entire from the working tree instead of the installed")
562			fmt.Fprintln(w, "  binary. This can reject `git push`, because the path it names is gone.")
563		}
564		fmt.Fprintln(w, "  Fix: reinstall the managed git hooks (any non-Entire hook is backed up).")
565	
566		if !force {
567			// Degrade to warn-only when there is nobody to ask. An agent or CI run
568			// must not be blocked on a prompt, and rewriting a repo's hooks
569			// unasked is worse than naming the command that does it.
570			if !interactive.CanPromptInteractively() {
571				fmt.Fprintln(w, "  Run `entire doctor --force` to apply it.")
572				return nil
573			}
574			proceed, promptErr := confirmDoctorFix(ctx, w, "Reinstall Entire git hooks?")
575			if promptErr != nil {
576				return promptErr
577			}
578			if !proceed {
579				return nil
580			}
581		}
582	
583		if _, err := strategy.ReinstallGitHooks(ctx); err != nil {
584			return fmt.Errorf("failed to reinstall git hooks: %w", err)
585		}
586		fmt.Fprintln(w, "  ✓ Fixed: git hooks reinstalled")
587		return nil
588	}
589	
590	// checkHookDrift warns when an installed agent's Entire hook config is out of
591	// date — an older release wrote Claude Code tool matchers that no longer fire,
592	// or a repo committed a Pi/OpenCode extension that the template has since moved
593	// past. Read-only; the fix is `entire enable --force`. Stays silent for agents
594	// that aren't installed here or don't implement a drift check.
595	func checkHookDrift(cmd *cobra.Command) {
596		ctx := cmd.Context()
597		w := cmd.OutOrStdout()
598		for _, name := range GetAgentsWithHooksInstalled(ctx) {
599			ag, err := agent.Get(name)
600			if err != nil {
601				continue
602			}
603			hf, ok := agent.AsHookFreshness(ag)
604			if !ok {
605				continue
606			}
607			displayName := string(ag.Type())
608			switch hf.CheckHookConfig(ctx) {
609			case agent.HooksAbsent:
610				// Not installed in this repo — nothing to report.
611			case agent.HooksCurrent:
612				fmt.Fprintf(w, "✓ %s hook config: OK\n", displayName)
613			case agent.HooksOutdated:
614				fmt.Fprintf(w, "%s hooks: OUT OF DATE\n", displayName)
615				fmt.Fprintln(w, "  The installed hook config no longer matches what this CLI writes,")
616				fmt.Fprintln(w, "  so some or all hooks may silently not fire.")
617				fmt.Fprintln(w, "  Run `entire enable --force` to update it.")
618			}
619		}
620	}
621	
622	// checkCodexHookTrust reports whether Codex can discover the authoritative
623	// hooks file, whether its Entire-managed event set is current, and whether the
624	// local Codex config has approval records for every declared hook. All checks
625	// are structural; Entire never computes or copies Codex trust hashes.
626	func checkCodexHookTrust(cmd *cobra.Command) {
627		location, err := codex.ResolveHookLocation(cmd.Context())
628		if err != nil {
629			if !codex.WorktreeProjectLayerExists(cmd.Context()) && !codex.HasWorktreeLocalEntireHooks(cmd.Context()) {
630				return
631			}
632			w := cmd.OutOrStdout()
633			var unsupported *codex.UnsupportedHookLocationError
634			if errors.As(err, &unsupported) {
635				fmt.Fprintln(w, "Codex hooks: UNSUPPORTED HOOK LOCATION")
636				fmt.Fprintf(w, "  Current Codex derives this checkout's shared hook root as %s.\n", unsupported.HookRoot)
637				if unsupported.Location.LegacyHooksPath != "" {
638					fmt.Fprintln(w, "  Entire will not write there. Remove ignored local hooks with `entire agent remove codex`.")
639				} else {
640					fmt.Fprintln(w, "  Entire will not install or remove hooks at this user-wide location.")
641				}
642			} else {
643				fmt.Fprintln(w, "Codex hooks: UNRESOLVED")
644				fmt.Fprintf(w, "  Entire could not resolve Codex's authoritative hooks file: %v\n", err)
645				fmt.Fprintln(w, "  Fix the repository metadata before installing or removing Codex hooks.")
646			}
647			return
648		}
649		legacy := codex.HasLegacyEntireHooks(cmd.Context())
650		inspection := codex.InspectHookConfig(cmd.Context())
651		w := cmd.OutOrStdout()
652		switch inspection.State {
653		case codex.HookFileAbsent, codex.HookFileUserOnly:
654			if legacy {
655				fmt.Fprintln(w, "Codex hooks: MISPLACED")
656				fmt.Fprintln(w, "  Entire hooks exist only in this linked checkout's worktree-local .codex/hooks.json,")
657				fmt.Fprintln(w, "  which current Codex ignores. Run `entire enable` to migrate them to the shared repository hook file.")
658			}
659			return
660		case codex.HookFileInvalid:
661			fmt.Fprintln(w, "Codex hooks: INVALID")
662			fmt.Fprintf(w, "  The authoritative .codex/hooks.json cannot be inspected: %v\n", inspection.Err)
663			fmt.Fprintln(w, "  Fix or restore the file before running `entire enable`.")
664			return
665		case codex.HookFileEntire:
666		}
667	
668		if !location.ProjectLayerExists() {
669			fmt.Fprintln(w, "Codex hooks: PROJECT LAYER MISSING")
670			fmt.Fprintln(w, "  The authoritative hooks file exists, but this linked checkout has no .codex directory,")
671			fmt.Fprintln(w, "  so current Codex does not discover it. Run `entire enable` from this checkout.")
672			return
673		}
674		missing := inspection.Missing
675		trust := codex.InspectHookTrust(cmd.Context())
676	
677		if len(missing) == 0 {
678			fmt.Fprintln(w, "✓ Codex hooks: INSTALLED")
679		}
680	
681		if len(missing) > 0 {
682			fmt.Fprintln(w, "Codex hooks: OUT OF DATE")
683			fmt.Fprintf(w, "  %d hook(s) the CLI installs today aren't declared in .codex/hooks.json:\n", len(missing))
684			for _, ev := range missing {
685				fmt.Fprintf(w, "    - %s\n", ev)
686			}
687			fmt.Fprintln(w, "  Run `entire enable` to refresh the hooks file.")
688		}
689	
690		switch {
691		case len(trust.Declared) > 0 && !trust.Known:
692			fmt.Fprintln(w, "Codex hook trust: UNKNOWN")
693			fmt.Fprintln(w, "  The hooks are installed, but Codex's local approval records could not be read.")
694			fmt.Fprintln(w, "  Open /hooks inside Codex to review their active state.")
695		case len(trust.Gaps) > 0:
696			fmt.Fprintln(w, "Codex hook trust: REVIEW NEEDED")
697			fmt.Fprintf(w, "  %d installed hook(s) have no approval record at the authoritative path:\n", len(trust.Gaps))
698			for _, ev := range trust.Gaps {
699				fmt.Fprintf(w, "    - %s\n", ev)
700			}
701			fmt.Fprintln(w, "  Open /hooks inside Codex to approve them.")
702		case len(trust.Declared) > 0:
703			fmt.Fprintln(w, "✓ Codex hook approval records: PRESENT")
704		}
705	
706		if legacy {
707			fmt.Fprintln(w, "Codex hooks: LEGACY COPY FOUND")
708			fmt.Fprintln(w, "  Run `entire enable` to remove only Entire-managed entries from this checkout's ignored legacy file.")
709		}
710	}
