712	// canDeleteShadowBranch checks if a shadow branch can be safely deleted.
713	// Returns true if no other sessions (besides excludeSessionID) need this branch.
714	func canDeleteShadowBranch(ctx context.Context, shadowBranch, excludeSessionID string) (bool, error) {
715		states, err := strategy.ListSessionStates(ctx)
716		if err != nil {
717			return false, fmt.Errorf("failed to list session states: %w", err)
718		}
719	
720		for _, state := range states {
721			if state.SessionID == excludeSessionID {
722				continue
723			}
724			otherShadow := checkpoint.ShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
725			if otherShadow == shadowBranch && state.StepCount > 0 {
726				return false, nil
727			}
728		}
729	
730		return true, nil
731	}

