   590	// checkHookDrift warns when an installed agent's Entire hook config is out of
   591	// date — an older release wrote Claude Code tool matchers that no longer fire,
   592	// or a repo committed a Pi/OpenCode extension that the template has since moved
   593	// past. Read-only; the fix is `entire enable --force`. Stays silent for agents
   594	// that aren't installed here or don't implement a drift check.
   595	func checkHookDrift(cmd *cobra.Command) {
   596		ctx := cmd.Context()
   597		w := cmd.OutOrStdout()
   598		for _, name := range GetAgentsWithHooksInstalled(ctx) {
   599			ag, err := agent.Get(name)
   600			if err != nil {
   601				continue
   602			}
   603			hf, ok := agent.AsHookFreshness(ag)
   604			if !ok {
   605				continue
   606			}
   607			displayName := string(ag.Type())
   608			switch hf.CheckHookConfig(ctx) {
   609			case agent.HooksAbsent:
   610				// Not installed in this repo — nothing to report.
   611			case agent.HooksCurrent:
   612				fmt.Fprintf(w, "✓ %s hook config: OK\n", displayName)
   613			case agent.HooksOutdated:
   614				fmt.Fprintf(w, "%s hooks: OUT OF DATE\n", displayName)
   615				fmt.Fprintln(w, "  The installed hook config no longer matches what this CLI writes,")
   616				fmt.Fprintln(w, "  so some or all hooks may silently not fire.")
   617				fmt.Fprintln(w, "  Run `entire enable --force` to update it.")
   618			}
   619		}
   620	}
