   622	// checkCodexHookTrust reports whether Codex can discover the authoritative
   623	// hooks file, whether its Entire-managed event set is current, and whether the
   624	// local Codex config has approval records for every declared hook. All checks
   625	// are structural; Entire never computes or copies Codex trust hashes.
   626	func checkCodexHookTrust(cmd *cobra.Command) {
   627		location, err := codex.ResolveHookLocation(cmd.Context())
   628		if err != nil {
   629			if !codex.WorktreeProjectLayerExists(cmd.Context()) && !codex.HasWorktreeLocalEntireHooks(cmd.Context()) {
   630				return
   631			}
   632			w := cmd.OutOrStdout()
   633			var unsupported *codex.UnsupportedHookLocationError
   634			if errors.As(err, &unsupported) {
   635				fmt.Fprintln(w, "Codex hooks: UNSUPPORTED HOOK LOCATION")
   636				fmt.Fprintf(w, "  Current Codex derives this checkout's shared hook root as %s.\n", unsupported.HookRoot)
   637				if unsupported.Location.LegacyHooksPath != "" {
   638					fmt.Fprintln(w, "  Entire will not write there. Remove ignored local hooks with `entire agent remove codex`.")
   639				} else {
   640					fmt.Fprintln(w, "  Entire will not install or remove hooks at this user-wide location.")
   641				}
   642			} else {
   643				fmt.Fprintln(w, "Codex hooks: UNRESOLVED")
   644				fmt.Fprintf(w, "  Entire could not resolve Codex's authoritative hooks file: %v\n", err)
   645				fmt.Fprintln(w, "  Fix the repository metadata before installing or removing Codex hooks.")
   646			}
   647			return
   648		}
   649		legacy := codex.HasLegacyEntireHooks(cmd.Context())
   650		inspection := codex.InspectHookConfig(cmd.Context())
   651		w := cmd.OutOrStdout()
   652		switch inspection.State {
   653		case codex.HookFileAbsent, codex.HookFileUserOnly:
   654			if legacy {
   655				fmt.Fprintln(w, "Codex hooks: MISPLACED")
   656				fmt.Fprintln(w, "  Entire hooks exist only in this linked checkout's worktree-local .codex/hooks.json,")
   657				fmt.Fprintln(w, "  which current Codex ignores. Run `entire enable` to migrate them to the shared repository hook file.")
   658			}
   659			return
   660		case codex.HookFileInvalid:
   661			fmt.Fprintln(w, "Codex hooks: INVALID")
   662			fmt.Fprintf(w, "  The authoritative .codex/hooks.json cannot be inspected: %v\n", inspection.Err)
   663			fmt.Fprintln(w, "  Fix or restore the file before running `entire enable`.")
   664			return
   665		case codex.HookFileEntire:
   666		}
   667	
   668		if !location.ProjectLayerExists() {
   669			fmt.Fprintln(w, "Codex hooks: PROJECT LAYER MISSING")
   670			fmt.Fprintln(w, "  The authoritative hooks file exists, but this linked checkout has no .codex directory,")
   671			fmt.Fprintln(w, "  so current Codex does not discover it. Run `entire enable` from this checkout.")
   672			return
   673		}
   674		missing := inspection.Missing
   675		trust := codex.InspectHookTrust(cmd.Context())
   676	
   677		if len(missing) == 0 {
   678			fmt.Fprintln(w, "✓ Codex hooks: INSTALLED")
   679		}
   680	
   681		if len(missing) > 0 {
   682			fmt.Fprintln(w, "Codex hooks: OUT OF DATE")
   683			fmt.Fprintf(w, "  %d hook(s) the CLI installs today aren't declared in .codex/hooks.json:\n", len(missing))
   684			for _, ev := range missing {
   685				fmt.Fprintf(w, "    - %s\n", ev)
   686			}
   687			fmt.Fprintln(w, "  Run `entire enable` to refresh the hooks file.")
   688		}
   689	
   690		switch {
   691		case len(trust.Declared) > 0 && !trust.Known:
   692			fmt.Fprintln(w, "Codex hook trust: UNKNOWN")
   693			fmt.Fprintln(w, "  The hooks are installed, but Codex's local approval records could not be read.")
   694			fmt.Fprintln(w, "  Open /hooks inside Codex to review their active state.")
   695		case len(trust.Gaps) > 0:
   696			fmt.Fprintln(w, "Codex hook trust: REVIEW NEEDED")
   697			fmt.Fprintf(w, "  %d installed hook(s) have no approval record at the authoritative path:\n", len(trust.Gaps))
   698			for _, ev := range trust.Gaps {
   699				fmt.Fprintf(w, "    - %s\n", ev)
   700			}
   701			fmt.Fprintln(w, "  Open /hooks inside Codex to approve them.")
   702		case len(trust.Declared) > 0:
   703			fmt.Fprintln(w, "✓ Codex hook approval records: PRESENT")
   704		}
   705	
   706		if legacy {
   707			fmt.Fprintln(w, "Codex hooks: LEGACY COPY FOUND")
   708			fmt.Fprintln(w, "  Run `entire enable` to remove only Entire-managed entries from this checkout's ignored legacy file.")
   709		}
   710	}
