   157	// OutdatedHookAgents returns agents whose Entire hook config has drifted from
   158	// what the CLI would write today, for `entire status` and `entire doctor` to
   159	// surface. Agents that don't implement agent.HookFreshness are skipped: absence
   160	// of a drift check reads as "nothing to report", never as a warning.
   161	//
   162	// Every freshness implementation is asked directly so it can report a stale
   163	// artifact that no longer qualifies as an active installation. For generated-
   164	// file agents (Pi, OpenCode), the committed file *is* the installation, so a
   165	// repo that ships one gets drift warnings even where nobody ran
   166	// `entire agent add`.
   167	func OutdatedHookAgents(ctx context.Context) []types.AgentName {
   168		var outdated []types.AgentName
   169		for _, name := range agent.List() {
   170			ag, err := agent.Get(name)
   171			if err != nil {
   172				continue
   173			}
   174			if hf, ok := agent.AsHookFreshness(ag); ok && hf.CheckHookConfig(ctx) == agent.HooksOutdated {
   175				outdated = append(outdated, name)
   176			}
   177		}
   178		return outdated
   179	}
