   187	// agentDisplayNames maps agent names to their user-facing display names,
   188	// skipping names that aren't registered.
   189	func agentDisplayNames(names []types.AgentName) []string {
   190		displayNames := make([]string, 0, len(names))
   191		for _, name := range names {
   192			if ag, err := agent.Get(name); err == nil {
   193				displayNames = append(displayNames, string(ag.Type()))
   194			}
   195		}
   196		return displayNames
