   199	// JoinAgentNames joins agent names into a comma-separated string.
   200	func JoinAgentNames(names []types.AgentName) string {
   201		strs := make([]string, len(names))
   202		for i, n := range names {
   203			strs[i] = string(n)
   204		}
   205		return strings.Join(strs, ",")
   206	}

