485	func managedHookIsCurrent(groups []MatcherGroup, command string, timeoutSec int) bool {
486		count := 0
487		for _, group := range groups {
488			for _, hook := range group.Hooks {
489				if !isEntireHook(hook.Command) {
490					continue
491				}
492				if hook.Command != command || hook.Timeout != timeoutSec {
493					return false
494				}
495				count++
496			}
497		}
498		return count == 1
499	}
