const smoke="/private/tmp/entire-pr2052-smoke.aQ7M4v";
const root=`${smoke}/malformed/root`;
const linked=`${smoke}/malformed/linked`;
const cmds=[
  `git init -b main ${root}`,
  `git -C ${root} config user.name 'Entire Smoke'`,
  `git -C ${root} config user.email 'smoke@example.invalid'`,
  `touch ${root}/README.md`,
  `git -C ${root} add README.md`,
  `git -C ${root} commit --no-gpg-sign -m initial`,
  `git -C ${root} worktree add -b feature ${linked}`,
  `mkdir -p ${linked}/.codex`,
  `touch ${linked}/.codex/hooks.json`
];
for(const cmd of cmds){
 const r=await tools.exec_command({cmd,workdir:smoke,login:false,yield_time_ms:10000,max_output_tokens:6000});
 text(`CMD ${cmd}\nEXIT ${r.exit_code}\n${r.output}`);
 if(r.exit_code!==0) exit();
}

